class Solution {
public:
    int maxSum(vector<int>& nums) {
        bool seen[201] = {};
        int maxVal = nums[0];
        int sum = 0;
        for (int x : nums) {
            if (x > maxVal) maxVal = x;
            if (x >= 0 && !seen[x + 100]) {
                seen[x + 100] = true;
                sum += x;
            }
        }
        if (maxVal < 0) return maxVal;
        return sum;
    }
};
